function getEffectiveConfig() {
  const props = PropertiesService.getUserProperties();
  const savedBotToken = props.getProperty('BOT_TOKEN') || CONFIG.BOT_TOKEN;
  const savedChatId = props.getProperty('CHAT_ID') || CONFIG.CHAT_ID;
  let medications = [];
  const savedMedsJson = props.getProperty('MEDICATIONS');
  if (savedMedsJson) {
    try { medications = JSON.parse(savedMedsJson); } catch (e) {}
  }
  if (!medications || medications.length === 0) {
    medications = CONFIG.MEDICATIONS || [];
  }
  return { botToken: savedBotToken, chatId: savedChatId, medications: medications };
}

function sendTelegramMessage(botToken, chatId, htmlText) {
  if (!botToken || !chatId) {
    Logger.log('❌ Bot Token 또는 Chat ID가 설정되지 않았습니다.');
    return { ok: false };
  }
  const url = 'https://api.telegram.org/bot' + botToken + '/sendMessage';
  const payload = {
    chat_id: chatId,
    text: htmlText,
    parse_mode: 'HTML',
    disable_web_page_preview: true
  };
  try {
    const response = UrlFetchApp.fetch(url, {
      method: 'post',
      contentType: 'application/json',
      payload: JSON.stringify(payload),
      muteHttpExceptions: true
    });
    const resJson = JSON.parse(response.getContentText());
    if (resJson.ok) {
      Logger.log('✅ 텔레그램 메시지 발송 성공 (ChatID: ' + chatId + ')');
    } else {
      Logger.log('❌ 텔레그램 메시지 발송 실패: ' + response.getContentText());
    }
    return resJson;
  } catch (err) {
    Logger.log('❌ 발송 에러: ' + err.message);
    return { ok: false, error: err.message };
  }
}

function checkAndSendMedicationReminders() {
  Logger.log('🕒 복약 알림 체크 시작...');
  const config = getEffectiveConfig();
  if (!config.botToken || !config.chatId) return;
  const medications = config.medications;
  if (!medications || medications.length === 0) return;

  const now = new Date();
  const kstDateStr = Utilities.formatDate(now, 'Asia/Seoul', 'yyyy-MM-dd');
  const kstHour = parseInt(Utilities.formatDate(now, 'Asia/Seoul', 'HH'), 10);
  const kstMin = parseInt(Utilities.formatDate(now, 'Asia/Seoul', 'mm'), 10);

  let targetMin = (kstMin >= 30) ? 30 : 0;
  let targetHour = kstHour;

  const hh = String(targetHour).padStart(2, '0');
  const mm = String(targetMin).padStart(2, '0');
  const slot24 = hh + ':' + mm;

  const suffix = targetHour < 12 ? 'A' : 'P';
  let h12 = targetHour % 12;
  if (h12 === 0) h12 = 12;
  const slot12 = h12 + ':' + mm + suffix;

  const props = PropertiesService.getUserProperties();
  const dispatchKey = 'DISPATCHED_' + kstDateStr + '_' + slot24;
  if (props.getProperty(dispatchKey)) {
    Logger.log('ℹ️ 해당 시간대(' + slot24 + ') 알림은 이미 발송되었습니다.');
    return;
  }

  const pendingMeds = medications.filter(med => {
    if (med.active === false) return false;
    if (med.startDate && kstDateStr < med.startDate) return false;
    if (med.endDate && kstDateStr > med.endDate) return false;
    const schedules = med.scheduleTimes || [];
    return schedules.some(slot => slot === slot24 || slot === slot12);
  });

  if (pendingMeds.length === 0) {
    Logger.log('ℹ️ 현재 시간대(' + slot24 + ')에 복약할 약품이 없습니다.');
    return;
  }

  let msg = '⏰ <b>MediOnTime 복약 알림 (' + slot24 + ')</b>\\n\\n';
  pendingMeds.forEach((med, idx) => {
    const dosageInfo = med.dosage ? ' <i>(' + med.dosage + ')</i>' : '';
    msg += '<b>' + (idx + 1) + '. ' + med.name + '</b>' + dosageInfo + '\\n';
  });
  msg += '\\n복약 후 체크해 주세요! ✨\\n👉 <a href="https://mediontime.github.io">MediOnTime 열기</a>';

  const res = sendTelegramMessage(config.botToken, config.chatId, msg);
  if (res && res.ok) {
    props.setProperty(dispatchKey, new Date().toISOString());
  }
}

function setupAutoTriggers() {
  const triggers = ScriptApp.getProjectTriggers();
  for (let i = 0; i < triggers.length; i++) {
    if (triggers[i].getHandlerFunction() === 'checkAndSendMedicationReminders') {
      ScriptApp.deleteTrigger(triggers[i]);
    }
  }
  ScriptApp.newTrigger('checkAndSendMedicationReminders').timeBased().everyMinutes(10).create();
  Logger.log('🎉 10분 주기 자동 복약 알림 트리거가 성공적으로 등록되었습니다!');
}

